import random, math
random.seed(0)
sims, days = 20000, 28
def run(k):
    hits = 0
    for _ in range(sims):
        s = [0.0] * k
        hit = False
        for d in range(1, days + 1):
            for m in range(k):
                s[m] += random.gauss(0, 1)
                if s[m] / math.sqrt(d) > 1.96:
                    hit = True
            if hit:
                break
        hits += hit
    return hits / sims
for k in (1, 8):
    print(k, "metric(s):", round(run(k), 3))
